/* Credit Platform: a guided reading of the product, with reference captures and explicitly local examples. */
const CR_GUIDE='https://github.com/catalisaio/wpp.bb.catalisa.io/blob/master/docs/guides/credito-em-camadas-guia.md';
const CR_STAGES=[
 {id:'receive',label:'Receber',title:'Uma proposta chega.<br>O contexto vem junto.',copy:'A fila aproxima propostas, informações e sinais para a equipe começar a análise. Abrir um caso é continuar um trabalho, com um ponto de partida organizado.',who:'QUEM ORIGINA + QUEM ANALISA',result:'Uma proposta pronta para ser lida.',file:'credit-queue.png',shot:'Fila de análise da mesa',detail:'O material de referência reúne propostas de modalidades diferentes na mesma mesa.'},
 {id:'assess',label:'Avaliar',title:'A regra encontra<br>a realidade do caso.',copy:'Política, condições e simulação ajudam a estruturar a avaliação. O que falta também precisa aparecer para quem decide.',who:'POLÍTICA + MESA DE CRÉDITO',result:'Uma avaliação que pode ser explicada.',file:'credit-policy.png',shot:'Política de crédito na mesa',detail:'Parâmetros da casa e do produto têm lugares próprios no material da plataforma.'},
 {id:'formalize',label:'Formalizar',title:'Aceitar uma proposta<br>é outro começo.',copy:'O aceite dá origem à operação. Documentos, autorizações e condições de liberação continuam a fazer parte do percurso.',who:'CLIENTE + FORMALIZAÇÃO + OPERAÇÃO',result:'Uma operação com próximos passos definidos.',file:'credit-operation.png',shot:'Operações e condições de liberação',detail:'A captura mostra operações aceitas que ainda aguardam autorização ou outras condições.'},
 {id:'follow',label:'Acompanhar',title:'O trabalho continua<br>depois da contratação.',copy:'Carteira, recebimentos e obrigações precisam de acompanhamento. A operação preserva o contexto para o que acontece ao longo do tempo.',who:'CARTEIRA + OPERAÇÃO + RELACIONAMENTO',result:'Uma visão para continuar o trabalho.',file:'credit-portfolio.png',shot:'Carteira na mesa de crédito',detail:'Uma leitura da posição e da exposição da carteira no ambiente demonstrativo.'}
];
function crShot(file,alt,cls='',eager=false){return `<button class="cr-shot ${cls}" data-gallery-file="${file}" data-gallery-product="credit" aria-label="Ampliar ${alt}"><img src="/assets/screens/${file}" alt="${alt}" ${eager?'fetchpriority="high"':'loading="lazy"'}><span>Explorar captura ↗</span></button>`;}
function crDossierArt(){return `<svg class="cr-dossier-art" viewBox="0 0 440 420" aria-hidden="true"><g fill="none" stroke="#8b6a9d" stroke-width=".7"><circle cx="235" cy="210" r="156"/><path d="M40 210H420M235 25V400" stroke-dasharray="2 8"/></g><g class="cr-paper cr-paper-back"><path d="M125 136L246 66L364 134V287L243 357L125 289Z" fill="#66477b"/><path d="M125 136L246 206L364 136" fill="none" stroke="#9270aa"/></g><g class="cr-paper cr-paper-middle"><path d="M100 113L221 43L339 111V264L218 334L100 266Z" fill="#9068aa"/><path d="M100 113L221 183L339 113" fill="none" stroke="#ba97d0"/></g><g class="cr-paper cr-paper-front"><path d="M75 90L196 20L314 88V241L193 311L75 243Z" fill="#ceb3df"/><path d="M103 113L194 60L282 111L191 164Z" fill="#b495cb"/><path d="M103 146L217 212M103 171L246 254M103 195L204 253" stroke="#9472ae" stroke-width="2"/><path d="M75 223L193 291L314 221V246L193 316L75 248Z" fill="#e7ac76"/></g><circle class="cr-dossier-sun" cx="345" cy="290" r="25" fill="#e8c06d"/><path d="M332 290L341 299L359 280" fill="none" stroke="#faf1d4" stroke-width="2"/></svg>`;}
function crJourneyPanel(s,i){return `<section class="cr-journey-panel" id="cr-panel-${s.id}" role="tabpanel" aria-labelledby="cr-tab-${s.id}" ${i?'hidden':''}><div class="cr-stage-copy"><span class="cr-eyebrow">${s.who}</span><h3>${s.title}</h3><p>${s.copy}</p><div class="cr-stage-output"><span>O QUE GANHA FORMA</span><strong>${s.result}</strong></div><button data-cr-next="${i}" class="text-link">${i===3?'Voltar ao começo ↺':'Próximo momento →'}</button></div><div class="cr-stage-visual"><div class="cr-window-bar"><span>0${i+1} / ${s.label.toUpperCase()}</span><span>CAPTURA DE REFERÊNCIA</span></div>${crShot(s.file,s.shot,'cr-stage-shot')}<p>${s.detail}</p>${i===1?`<div class="cr-simulation-aside">${crShot('credit-simulator.png','simulação de condições na mesa')}<span>As condições também<br>precisam de uma leitura clara.</span></div>`:''}</div></section>`;}
const CR_EVIDENCE={complete:{label:'Informações reunidas',title:'O caso pode ser lido com contexto.',copy:'Os elementos previstos neste exemplo estão reunidos. A equipe ainda precisa avaliar o caso conforme a política e as responsabilidades definidas.',state:'Contexto organizado',items:['Pedido descrito','Documentos de referência','Política identificada'],result:'Pronto para revisão'},missing:{label:'Um dado pendente',title:'Uma falta também é uma informação.',copy:'O exemplo destaca o que ainda não foi recebido. Um dado ausente continua identificado como ausente, sem virar um número inventado.',state:'Complementar contexto',items:['Pedido descrito','Informação ainda não recebida','Política identificada'],result:'Aguardar complemento'},human:{label:'Revisão pela mesa',title:'Uma pessoa entra no próximo passo.',copy:'A leitura passa pela mesa. A demonstração separa apoio à análise de uma decisão registrada por quem tem essa responsabilidade.',state:'Revisão humana',items:['Contexto organizado','Pontos para revisar','Responsável pela avaliação'],result:'Aguardando a mesa'}};
const CR_COLLATERALS={receivables:{label:'Recebíveis',glyph:'≋',title:'O que já existe a receber ganha contexto.',copy:'Documentos e referências do recebível entram na composição da proposta e acompanham a operação.',detail:'O guia apresenta a antecipação de recebíveis como pacote conectado à camada comum.'},vehicle:{label:'Veículo',glyph:'↗',title:'A garantia traz informações próprias.',copy:'Dados do veículo e condições da garantia acrescentam responsabilidades específicas à jornada.',detail:'O material explora o produto com garantia de veículo. Integrações e condições precisam ser verificadas por implementação.'},property:{label:'Imóvel',glyph:'⌂',title:'Outro lastro, outras referências.',copy:'O imóvel acrescenta informações e condições próprias, sobre a mesma organização do processo.',detail:'A presença da modalidade no material não confirma que todas as etapas externas estejam disponíveis.'},personal:{label:'Pessoal',glyph:'◉',title:'O produto também pode seguir sem uma garantia real.',copy:'A modalidade reúne parâmetros, condições e política conforme a definição do produto de crédito.',detail:'O guia inclui o crédito pessoal entre as composições exploradas pela mesa.'},payroll:{label:'Consignado',glyph:'⊞',title:'A relação com a folha participa da composição.',copy:'Convênio, margem e informações de repasse entram no contexto específico do produto.',detail:'O material registra telas e percursos de consignado no ambiente de demonstração.'}};
function crPage(p,blocks){const parts=[['banking-product-portfolio','Estruturar o produto'],['decision-engine','Organizar a política'],['calculations-engine','Calcular as condições'],['pricing-engine','Compor o preço'],['document-template','Preparar documentos'],['e-signature','Conduzir a assinatura'],['data-store','Manter o contexto'],['baas','Conectar a conta']];return `<div class="cr-page" id="cr-page"><section class="cr-hero"><div class="wrap"><div class="cr-hero-heading"><div><span class="cr-eyebrow">CATALISA / CREDIT PLATFORM</span><h1>Crédito tem começo.<br>A operação<br><em>continua.</em></h1></div>${crDossierArt()}</div><div class="cr-hero-description"><p>Da proposta à carteira, uma composição<br>para dar continuidade ao trabalho.</p><a href="#cr-percurso" class="text-link">Percorra a experiência ↓</a><button data-cr-motion aria-pressed="false">Ⅱ Pausar movimento</button></div><div class="cr-hero-screen"><span class="cr-window-bar"><i></i><i></i><i></i><span>MESA DE CRÉDITO / UMA VISÃO DA OPERAÇÃO</span></span>${crShot('credit-queue.png','fila de análise de crédito','',true)}<span class="cr-hero-screen-caption">Interface de referência · ambiente demonstrativo · amplie para ler os detalhes</span></div></div></section><section class="cr-intro wrap"><span class="cr-eyebrow">O PRODUTO É MAIS DO QUE A PROPOSTA</span><div><h2>Quem cria define o produto.<br><em>Quem opera continua a história.</em></h2><p>Catálogo, política e condições organizam a construção. A mesa reúne a fila, o dossiê e o acompanhamento. Duas perspectivas para um processo que precisa continuar fazendo sentido.</p></div><div class="cr-two-works"><div><span>01 / CONSTRUIR</span><p>Produto. Política.<br>Condições. Documentos.</p></div><span class="cr-two-bridge" aria-hidden="true">↔</span><div><span>02 / OPERAR</span><p>Proposta. Decisão.<br>Operação. Carteira.</p></div></div></section><section class="cr-journey" id="cr-percurso"><div class="wrap"><div class="cr-section-heading"><div><span class="cr-eyebrow">UMA PROPOSTA, QUATRO MOMENTOS</span><h2>Entre no processo.<br><em>Veja o que muda.</em></h2></div><p>Escolha um momento para entender<br>o trabalho e explorar a interface.</p></div><div class="cr-journey-tabs" role="tablist" aria-label="Momentos da experiência de crédito">${CR_STAGES.map((s,i)=>`<button id="cr-tab-${s.id}" data-cr-stage="${s.id}" role="tab" aria-controls="cr-panel-${s.id}" aria-selected="${!i}" tabindex="${i?-1:0}"><span>0${i+1}</span>${s.label}<i>→</i></button>`).join('')}</div>${CR_STAGES.map(crJourneyPanel).join('')}</div></section><section class="cr-evidence wrap"><div class="cr-evidence-copy"><span class="cr-eyebrow">ENTENDER TAMBÉM É SABER O QUE FALTA</span><h2>Uma leitura melhor<br>começa pelo<br><em>contexto certo.</em></h2><p>Informações, ausência de dados e revisão humana têm significados diferentes. Explore uma demonstração simplificada dessa leitura.</p><div class="cr-evidence-options" role="group" aria-label="Situação da análise ilustrativa">${Object.entries(CR_EVIDENCE).map(([key,s],i)=>`<button data-cr-evidence="${key}" aria-pressed="${!i}">${s.label}<span>↗</span></button>`).join('')}</div><small>Exemplo de leitura do processo. Não executa consulta, análise ou decisão de crédito.</small></div><div class="cr-evidence-dossier" id="cr-evidence-dossier" data-state="complete"><div class="cr-dossier-top"><span>DOSSIÊ / EXEMPLO 024</span><span id="cr-evidence-state">Contexto organizado</span></div><div class="cr-dossier-identity"><span>◒</span><div><strong>Um pedido com contexto.</strong><small>Informações fictícias para explorar a experiência.</small></div></div><ol id="cr-evidence-items">${CR_EVIDENCE.complete.items.map((x,i)=>`<li><span>0${i+1}</span>${x}<i>✓</i></li>`).join('')}</ol><div class="cr-evidence-result"><span>PRÓXIMO PASSO DO EXEMPLO</span><strong id="cr-evidence-result">Pronto para revisão</strong></div><div class="cr-evidence-explanation" role="status"><h3 id="cr-evidence-title">${CR_EVIDENCE.complete.title}</h3><p id="cr-evidence-copy">${CR_EVIDENCE.complete.copy}</p></div></div></section><section class="cr-composition" id="cr-composicao"><div class="wrap"><div class="cr-composition-heading"><span class="cr-eyebrow">CRÉDITO EM CAMADAS</span><h2>O processo tem uma base.<br><em>O produto acrescenta o seu contexto.</em></h2><p>Uma camada comum organiza etapas recorrentes.<br>Cada modalidade acrescenta o que é específico.</p></div><div class="cr-composition-layout"><div class="cr-common-base"><span>O QUE SUSTENTA A CONTINUIDADE</span><h3>Uma base de trabalho.</h3><div><span>Proposta e aceite</span><span>Operação e liberação</span><span>Pagamentos</span><span>Histórico e acompanhamento</span></div><svg viewBox="0 0 470 170" role="img" aria-label="Camadas de uma base comum de crédito"><path d="M25 85L230 20L445 85L240 150Z" fill="#77508f"/><path d="M25 85V101L240 166V150Z" fill="#624078"/><path d="M240 150L445 85V101L240 166Z" fill="#4c2f62"/><path d="M85 69L231 23L385 69L239 115Z" fill="#bb9dcd"/><path d="M85 69V81L239 127V115Z" fill="#9877ad"/><path d="M239 115L385 69V81L239 127Z" fill="#78568e"/><path class="cr-common-trace" d="M130 69L233 37L340 69L237 101Z" fill="none" stroke="#e4b17f" stroke-width="1.5" stroke-dasharray="3 9"/></svg></div><div class="cr-collateral"><div class="cr-collateral-tabs" role="group" aria-label="Explore uma modalidade">${Object.entries(CR_COLLATERALS).map(([key,s],i)=>`<button data-cr-collateral="${key}" aria-pressed="${!i}">${s.label}</button>`).join('')}</div><div class="cr-collateral-detail" role="status"><span class="cr-collateral-glyph" id="cr-collateral-glyph">≋</span><span class="cr-eyebrow" id="cr-collateral-label">RECEBÍVEIS</span><h3 id="cr-collateral-title">${CR_COLLATERALS.receivables.title}</h3><p id="cr-collateral-copy">${CR_COLLATERALS.receivables.copy}</p><small id="cr-collateral-detail">${CR_COLLATERALS.receivables.detail}</small></div></div></div></div></section><section class="cr-continuity wrap"><div class="cr-section-heading"><div><span class="cr-eyebrow">A CARTEIRA NÃO TERMINA NO DESEMBOLSO</span><h2>O que vem depois<br><em>também faz parte.</em></h2></div><p>Acompanhar, revisar e continuar.<br>O produto mantém espaço para a vida da operação.</p></div><div class="cr-continuity-gallery"><article><span class="cr-eyebrow">01 / ACORDOS</span><h3>Quando a operação<br>precisa de outro caminho.</h3><p>A renegociação aparece no material como uma frente de trabalho, com condições e aceite que precisam ser acompanhados.</p>${crShot('credit-latest-agreements.png','acordos e renegociação na mesa')}<small>Captura de staging · guia atualizado em 25/09/2026</small></article><article><span class="cr-eyebrow">02 / MONITORAMENTO</span><h3>O contrato continua<br>a pedir atenção.</h3><p>Obrigações e informações de acompanhamento ajudam a equipe a ler o que mudou ao longo da operação.</p>${crShot('credit-latest-covenants.png','monitoramento de obrigações na mesa')}<small>Captura de staging · guia atualizado em 25/09/2026</small></article></div></section><section class="cr-partner"><div class="wrap"><div><span class="cr-eyebrow">O CONTEXTO ALCANÇA QUEM PARTICIPA</span><h2>Quem origina<br>também precisa<br><em>acompanhar.</em></h2><p>O portal do parceiro é outra perspectiva do produto: uma leitura do que foi originado e do relacionamento com a operação.</p><small>Interface capturada no material de referência.<br>Dados de demonstração.</small></div><div class="cr-partner-frame"><span class="cr-window-bar"><span>PORTAL DO PARCEIRO</span><span>AMPLIAR ↗</span></span>${crShot('credit-portal.jpg','portal do parceiro de crédito')}</div></div></section><section class="cr-parts wrap"><div><span class="cr-eyebrow">AS PEÇAS POR TRÁS DO PERCURSO</span><h2>Cada responsabilidade<br>encontra <em>uma capacidade.</em></h2><p>O produto combina recursos conforme o escopo.<br>Os estágios do catálogo ajudam a entender cada peça.</p></div><div class="cr-parts-index">${parts.map(([slug,purpose],i)=>{const b=blocks.find(x=>x.slug===slug);return `<a href="/capacidades/${slug}/"><span>0${i+1}</span><div><strong>${purpose}</strong><small>${b?.name||slug}</small></div><span class="cr-part-status">${b?.status||'Consultar catálogo'}</span><i>↗</i></a>`}).join('')}</div></section><section class="cr-film wrap"><div><span class="cr-eyebrow">VEJA A MESA GANHAR ESPAÇO</span><h2>Um percurso visual<br>pelas <em>interfaces.</em></h2><p>Montagem das capturas de referência.<br>Não é uma gravação de concessão ou movimentação real.</p></div><video controls playsinline preload="none" poster="/assets/screens/credit-queue.png" aria-label="Montagem visual das interfaces de Credit Platform"><source src="/assets/media/credit-reel.mp4" type="video/mp4">Explore as capturas da página para conhecer as interfaces.</video></section><section class="cr-scope wrap"><span class="cr-eyebrow">O CONTEXTO DO MATERIAL</span><h2>Conhecer o produto.<br><em>Entender o seu estágio.</em></h2><div><p>Os guias registram frentes, implementações e limites diferentes. As capturas mostram ambientes de demonstração e staging, sem confirmar disponibilidade integral de cada modalidade ou provedor.</p><p>As experiências desta página são explicativas. A implantação exige definição de produto, política, parceiros e validação das integrações previstas.</p></div><a href="${CR_GUIDE}" target="_blank" rel="noopener" class="text-link">Consulte o guia e as referências ↗</a></section><section class="cr-closing"><div class="wrap"><span class="cr-eyebrow">CRÉDITO E BANKING / CONTINUIDADE</span><h2>O produto ganha força<br>quando as partes<br><em>trabalham juntas.</em></h2><div><a href="/ecossistema/banking/" class="text-link">Explore Banking Platform ↗</a><a href="/contato/" class="text-link">Converse com a Catalisa ↗</a></div></div></section></div>`;}
const crPreviousProduct=cProduct;cProduct=function(p,blocks){return p.slug==='credit'?crPage(p,blocks):crPreviousProduct(p,blocks)};
function crBind(){const page=document.getElementById('cr-page');if(!page)return;const tabs=[...page.querySelectorAll('[data-cr-stage]')];function stage(i,focus=false){tabs.forEach((t,j)=>{const active=i===j;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;if(active&&focus)t.focus({preventScroll:true});});}tabs.forEach((t,i)=>{t.addEventListener('click',()=>stage(i));t.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();stage(e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4,true);});});page.querySelectorAll('[data-cr-next]').forEach(b=>b.addEventListener('click',()=>stage((Number(b.dataset.crNext)+1)%4,true)));page.querySelector('[data-cr-motion]').addEventListener('click',e=>{const paused=page.classList.toggle('cr-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'▷ Retomar movimento':'Ⅱ Pausar movimento';});page.querySelectorAll('[data-cr-evidence]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.crEvidence,s=CR_EVIDENCE[key];page.querySelectorAll('[data-cr-evidence]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('cr-evidence-dossier').dataset.state=key;document.getElementById('cr-evidence-state').textContent=s.state;document.getElementById('cr-evidence-title').textContent=s.title;document.getElementById('cr-evidence-copy').textContent=s.copy;document.getElementById('cr-evidence-result').textContent=s.result;[...document.querySelectorAll('#cr-evidence-items>li')].forEach((li,i)=>{li.innerHTML=`<span>0${i+1}</span>${s.items[i]}<i>${key==='missing'&&i===1?'—':key==='human'&&i===1?'◉':'✓'}</i>`;});}));page.querySelectorAll('[data-cr-collateral]').forEach(b=>b.addEventListener('click',()=>{const s=CR_COLLATERALS[b.dataset.crCollateral];page.querySelectorAll('[data-cr-collateral]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('cr-collateral-label').textContent=s.label.toUpperCase();['glyph','title','copy','detail'].forEach(key=>document.getElementById('cr-collateral-'+key).textContent=s[key]);}));}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',crBind);
